(function(){var bar=document.querySelector('.hero__bar');if(bar){var onScrollBar=function(){bar.classList.toggle('is-stuck',window.scrollY>12)};window.addEventListener('scroll',onScrollBar,{passive:!0});onScrollBar()}
var burger=document.querySelector('.burger');var mmenu=document.getElementById('mmenu');var mx=mmenu?mmenu.querySelector('.mmenu__x'):null;if(burger&&mmenu){var openMenu=function(){mmenu.classList.add('is-open');burger.setAttribute('aria-expanded','true');document.body.style.overflow='hidden';if(mx)mx.focus()};var closeMenu=function(){mmenu.classList.remove('is-open');burger.setAttribute('aria-expanded','false');document.body.style.overflow=''};burger.addEventListener('click',openMenu);if(mx)mx.addEventListener('click',closeMenu);mmenu.addEventListener('click',function(e){if(e.target===mmenu||e.target.tagName==='A')closeMenu()});document.addEventListener('keydown',function(e){if(e.key==='Escape')closeMenu()})}
var reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;var revs=[].slice.call(document.querySelectorAll('.rv'));if(revs.length){if(reduce||!('IntersectionObserver' in window)){revs.forEach(function(el){el.classList.add('is-in')})}else{var io=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(!entry.isIntersecting)return;entry.target.classList.add('is-in');io.unobserve(entry.target)})},{threshold:.1,rootMargin:'0px 0px -5% 0px'});revs.forEach(function(el,i){el.style.transitionDelay=(i%4)*60+'ms';io.observe(el)});setTimeout(function(){revs.forEach(function(el){var r=el.getBoundingClientRect();if(r.top<window.innerHeight&&r.bottom>0)el.classList.add('is-in')})},400)}}
var fab=document.getElementById('ftFab');var toggleFab=function(){if(!fab)return;var visible=window.scrollY>window.innerHeight*1.1;fab.classList.toggle('is-shown',visible);fab.setAttribute('aria-hidden',visible?'false':'true');fab.tabIndex=visible?0:-1};if(fab){var ticking=!1;window.addEventListener('scroll',function(){if(ticking)return;ticking=!0;requestAnimationFrame(function(){ticking=!1;toggleFab()})},{passive:!0});toggleFab()}
var speedDial=document.getElementById('rrSpeedDial');var speedDialBtn=document.getElementById('rrSpeedDialBtn');var speedDialActions=document.getElementById('rrSpeedDialActions');if(speedDial&&speedDialBtn&&speedDialActions){var actionLinks=[].slice.call(speedDialActions.querySelectorAll('a'));var toggleSpeedDial=function(open){var isOpen=typeof open==='boolean'?open:!speedDial.classList.contains('is-open');speedDial.classList.toggle('is-open',isOpen);speedDialBtn.setAttribute('aria-expanded',isOpen?'true':'false');speedDialActions.setAttribute('aria-hidden',isOpen?'false':'true');actionLinks.forEach(function(a){a.tabIndex=isOpen?0:-1})};speedDialBtn.addEventListener('click',function(e){e.stopPropagation();toggleSpeedDial()});document.addEventListener('click',function(e){if(!speedDial.contains(e.target)&&speedDial.classList.contains('is-open')){toggleSpeedDial(!1)}});document.addEventListener('keydown',function(e){if(e.key==='Escape'&&speedDial.classList.contains('is-open')){toggleSpeedDial(!1);speedDialBtn.focus()}})}})()